import { spawn } from 'node:child_process';
import { win32 } from 'node:path';

// Only IDs generated by the Windows workflow channel, never session IDs or other apps.
export function validWorkflowTags(tags) {
  return Array.isArray(tags) && tags.length > 0 && tags.length <= 128 &&
    tags.every(tag => typeof tag === 'string' && tag.length <= 48 &&
      /^pharos-wf-[a-z0-9]+-[a-z0-9]+-[a-z0-9]+$/.test(tag));
}

// Keep the program fixed. Validated identifiers travel over stdin, not shell syntax.
const REMOVE_HISTORY_SCRIPT = `
$ErrorActionPreference = 'Stop'
$tags = [Console]::In.ReadToEnd() | ConvertFrom-Json
$nativeTags = @(foreach ($tag in $tags) { 'n#dsh-app://app#' + [string]$tag })
$history = [Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType=WindowsRuntime]::History
foreach ($tag in $nativeTags) {
  $history.Remove($tag, 'Notifications', 'electron.app.DeepSeek Harness')
}
foreach ($toast in $history.GetHistory('electron.app.DeepSeek Harness')) {
  if ($toast.Group -ceq 'Notifications' -and $nativeTags -ccontains $toast.Tag) {
    throw 'workflow notification remains in native history'
  }
}
`;

/** Remove retired workflow entries from Action Center; Web Notification.close() only hides them. */
export function removeWindowsWorkflowHistory(tags, {
  platform = process.platform, launch = spawn, systemRoot = process.env.SystemRoot ?? 'C:\\Windows', timeoutMs = 8000,
} = {}) {
  if (!validWorkflowTags(tags)) return Promise.reject(new Error('invalid workflow notification identifiers'));
  if (platform !== 'win32') return Promise.resolve(false);
  return new Promise((resolve, reject) => {
    const child = launch(win32.join(systemRoot, 'System32', 'WindowsPowerShell', 'v1.0', 'powershell.exe'),
      ['-NoProfile', '-NonInteractive', '-EncodedCommand', Buffer.from(REMOVE_HISTORY_SCRIPT, 'utf16le').toString('base64')],
      { shell: false, windowsHide: true, stdio: ['pipe', 'ignore', 'ignore'] });
    let settled = false;
    const finish = (error) => {
      if (settled) return;
      settled = true; clearTimeout(timer);
      if (error) { try { child.kill(); } catch { /* best effort after spawn/pipe failures */ } }
      error ? reject(error) : resolve(true);
    };
    const timer = setTimeout(() => {
      finish(new Error('workflow history cleanup timed out'));
    }, timeoutMs);
    child.once('error', finish);
    child.once('close', code => finish(code === 0 ? null : new Error('workflow history cleanup failed')));
    child.stdin.on('error', finish);
    try { child.stdin.end(JSON.stringify([...new Set(tags)])); } catch (error) { finish(error); }
  });
}
